package com.andye.warmod.block;import com.andye.warmod.block.entity.*;import com.andye.warmod.phalanx.PhalanxManager;import com.mojang.serialization.MapCodec;import java.util.function.BiConsumer;import net.minecraft.core.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;import org.jspecify.annotations.Nullable;
public final class PhalanxTurretBlock extends BaseEntityBlock implements WorldlyContainerHolder{private static final VoxelShape BASE_SHAPE=Shapes.or(Block.box(1,0,1,15,6,15),Block.box(3,6,3,13,16,13));private static final VoxelShape HEAD_SHAPE=Shapes.or(Block.box(2,0,2,14,9,14),Block.box(4,9,4,12,16,12));public static final MapCodec<PhalanxTurretBlock> CODEC=simpleCodec(PhalanxTurretBlock::new);public static final EnumProperty<PhalanxPart> PART=EnumProperty.create("part",PhalanxPart.class);public static final Property<Direction> FACING=HorizontalDirectionalBlock.FACING;public PhalanxTurretBlock(BlockBehaviour.Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(PART,PhalanxPart.BASE_00).setValue(FACING,Direction.NORTH));}@Override protected MapCodec<? extends PhalanxTurretBlock> codec(){return CODEC;}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(PART,FACING);}@Override protected RenderShape getRenderShape(BlockState s){return RenderShape.INVISIBLE;}@Override public @Nullable BlockEntity newBlockEntity(BlockPos p,BlockState s){return s.getValue(PART)==PhalanxPart.BASE_00?new PhalanxBlockEntity(p,s):null;}@Override public<T extends BlockEntity>@Nullable BlockEntityTicker<T> getTicker(Level l,BlockState s,BlockEntityType<T> type){return l.isClientSide()||s.getValue(PART)!=PhalanxPart.BASE_00?null:createTickerHelper(type,ModBlockEntities.PHALANX_TURRET,PhalanxBlockEntity::serverTick);}public static @Nullable PhalanxBlockEntity resolve(LevelAccessor l,BlockPos p,BlockState s){if(!s.is(ModBlocks.PHALANX_TURRET))return null;BlockPos c=s.getValue(PART).controller(p);return l.getBlockEntity(c)instanceof PhalanxBlockEntity be?be:null;}@Override protected VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return s.getValue(PART)==PhalanxPart.TOP_00?HEAD_SHAPE:BASE_SHAPE;}@Override public WorldlyContainer getContainer(BlockState s,LevelAccessor l,BlockPos p){return resolve(l,p,s);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player player,BlockHitResult hit){if(l.isClientSide())return InteractionResult.SUCCESS;PhalanxBlockEntity be=resolve(l,p,s);if(be==null)return InteractionResult.FAIL;if(player.isShiftKeyDown()){be.setEnabled(!be.enabled());player.sendSystemMessage(net.minecraft.network.chat.Component.literal("Phalanx "+(be.enabled()?"enabled":"disabled")));}else if(player instanceof net.minecraft.server.level.ServerPlayer serverPlayer)serverPlayer.openMenu(new net.fabricmc.fabric.api.menu.v1.ExtendedMenuProvider<com.andye.warmod.menu.ModMenus.PhalanxOpeningData>(){public com.andye.warmod.menu.ModMenus.PhalanxOpeningData getScreenOpeningData(net.minecraft.server.level.ServerPlayer viewer){return new com.andye.warmod.menu.ModMenus.PhalanxOpeningData(be.getBlockPos());}public net.minecraft.network.chat.Component getDisplayName(){return net.minecraft.network.chat.Component.translatable("container.war_mod.phalanx");}public net.minecraft.world.inventory.AbstractContainerMenu createMenu(int id,net.minecraft.world.entity.player.Inventory inv,Player viewer){return new com.andye.warmod.menu.PhalanxMenu(id,inv,be);}});return InteractionResult.SUCCESS_SERVER;}@Override protected boolean hasAnalogOutputSignal(BlockState s){return true;}@Override protected int getAnalogOutputSignal(BlockState s,Level l,BlockPos p,Direction d){PhalanxBlockEntity be=resolve(l,p,s);return be==null?0:(int)Math.ceil(be.rounds()*15.0/128.0);}@Override public BlockState playerWillDestroy(Level l,BlockPos p,BlockState s,Player player){if(l instanceof ServerLevel server)PhalanxStructure.teardown(server,p,s,true);return s;}@Override public void playerDestroy(Level l,Player p,BlockPos pos,BlockState s,@Nullable BlockEntity be,ItemStack tool){}@Override protected void onExplosionHit(BlockState s,ServerLevel l,BlockPos p,Explosion e,BiConsumer<ItemStack,BlockPos> hit){PhalanxStructure.teardown(l,p,s,true);}}

